<?php use App\Models\ProjectEmail; $emailPreference=App\Core\DB::one('SELECT ticket_email_enabled FROM users WHERE id=?',[$user['id']]); ?>
<section class="panel email-preferences" id="email-preferences"><div class="panel-header"><div><h2>Vos notifications e-mail</h2><p>Choisissez si vous souhaitez recevoir les nouvelles de vos tickets.</p></div><?= icon('bell') ?></div><form method="post" action="/account/notifications" class="stack"><?= csrf() ?><input type="hidden" name="_return" value="/settings#email-preferences"><label class="check-label"><input type="checkbox" name="ticket_email_enabled" value="1" <?= $emailPreference['ticket_email_enabled']?'checked':'' ?>>Recevoir les notifications des projets qui me concernent</label><p class="help-text">Cette préférence s’applique à tous vos projets. Elle ne désactive pas la validation d’adresse ni la récupération de mot de passe. Les notifications ne sont envoyées que si le projet les active.</p><button class="button subtle">Enregistrer ma préférence</button></form></section>
<?php if($user['role']==='admin'): ?>
<section class="panel email-settings" id="notifications"><div class="panel-header"><div><span class="eyebrow">LES BONNES NOUVELLES, AUX BONNES PERSONNES</span><h2>Notifications des projets</h2><p>Un réglage indépendant pour chaque projet.</p></div><?= icon('bell') ?></div>
<form method="get" action="/settings#notifications" class="email-project-picker"><label>Projet à configurer<select name="project"><?php foreach($projects as $candidate): ?><option value="<?= (int)$candidate['id'] ?>" <?= $candidate['id']===$project['id']?'selected':'' ?>><?= e($candidate['name']) ?></option><?php endforeach; ?></select></label><button class="button subtle">Afficher ce projet</button></form>
<?php if($project['id']): $mailConfig=ProjectEmail::get((int)$project['id']); $mailQueue=App\Core\DB::all('SELECT state,COUNT(*) n FROM notification_outbox WHERE project_id=? GROUP BY state',[$project['id']]); $mailRecent=App\Core\DB::all('SELECT n.state,n.attempts,n.created_at,n.sent_at,n.last_error,u.name,t.number FROM notification_outbox n JOIN users u ON u.id=n.recipient_id JOIN tickets t ON t.id=n.ticket_id WHERE n.project_id=? ORDER BY n.id DESC LIMIT 20',[$project['id']]); ?>
<form method="post" action="/projects/<?= (int)$project['id'] ?>/notifications" class="stack" data-email-settings><?= csrf() ?><input type="hidden" name="_return" value="/settings?project=<?= (int)$project['id'] ?>#notifications"><input type="hidden" name="version" value="<?= (int)$mailConfig['version'] ?>"><h3><?= e($project['name']) ?></h3><label class="check-label"><input type="checkbox" name="enabled" value="1" <?= $mailConfig['enabled']?'checked':'' ?>>Activer les notifications de ce projet</label><label class="check-label"><input type="checkbox" name="notify_actor" value="1" <?= $mailConfig['notify_actor']?'checked':'' ?>>Inclure également l’auteur de l’action parmi les destinataires concernés</label><p class="help-text">Cochez les destinataires de chaque événement. Une ligne vide désactive cet événement. Les réglages recommandés privilégient les personnes directement concernées ; les modifications générales restent désactivées pour limiter les e-mails.</p>
<div class="table-scroll"><table class="email-rules"><thead><tr><th>Événement</th><?php foreach(ProjectEmail::RECIPIENTS as $label): ?><th><?= e($label) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach(ProjectEmail::EVENTS as $event=>$label): ?><tr><th scope="row"><?= e($label) ?></th><?php foreach(ProjectEmail::RECIPIENTS as $role=>$roleLabel): ?><td><input type="checkbox" name="rules[<?= e($event) ?>][]" value="<?= e($role) ?>" <?= in_array($role,$mailConfig['rules'][$event]??[],true)?'checked':'' ?> aria-label="<?= e($label.' — '.$roleLabel) ?>" data-email-event="<?= e($event) ?>" data-email-role="<?= e($role) ?>"></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div>
<details <?= $mailConfig['recipients']?'open':'' ?>><summary>Personnes choisies pour ce projet</summary><div class="email-recipient-picker"><?php foreach($members as $member): ?><label class="check-label"><input type="checkbox" name="recipients[]" value="<?= (int)$member['id'] ?>" <?= in_array((int)$member['id'],$mailConfig['recipients'],true)?'checked':'' ?>><?= e($member['name']) ?><small><?= e($member['email']) ?></small></label><?php endforeach; ?></div><p class="help-text">Ces personnes reçoivent uniquement les événements dont la colonne « Personnes choisies » est cochée.</p></details>
<p class="help-text">Les comptes doivent être actifs, vérifiés et avoir accepté les notifications. Le responsable précédent est aussi prévenu d’une réaffectation si la colonne « Responsable individuel » est cochée. Les équipes sont celles liées au ticket ou au projet. Le demandeur interne est le compte rapporteur ; les adresses externes des formulaires ne reçoivent pas ces messages internes. Un ticket terminé utilise l’événement « Ticket terminé », plutôt que « Changement d’état ».</p>
<div class="llm-actions"><button class="button primary">Enregistrer les notifications du projet</button><button type="button" class="button subtle" data-email-recommended>Rétablir les choix recommandés</button></div></form>
<details class="email-delivery"><summary>Suivi des envois de ce projet</summary><p class="help-text">Une action regroupe les événements concernant le même ticket et la même personne. Les e-mails contiennent le résumé et un lien de connexion, sans recopier descriptions, commentaires ni fichiers.</p><div class="llm-actions"><?php foreach($mailQueue as $queue): ?><span class="pill neutral"><?= e(['pending'=>'En attente','sending'=>'En cours','sent'=>'Acceptés par le transport','cancelled'=>'Annulés','failed'=>'En échec'][$queue['state']]) ?> : <?= (int)$queue['n'] ?></span><?php endforeach; ?></div><div class="table-scroll"><table class="email-rules"><thead><tr><th>Ticket</th><th>Destinataire</th><th>État</th><th>Tentatives</th><th>Date UTC</th></tr></thead><tbody><?php foreach($mailRecent as $delivery): ?><tr><td><?= e($project['project_key'].'-'.$delivery['number']) ?></td><td><?= e($delivery['name']) ?></td><td><?= e(['pending'=>'En attente','sending'=>'En cours','sent'=>'Accepté','cancelled'=>'Annulé','failed'=>'En échec'][$delivery['state']]) ?><?php if($delivery['last_error']): ?><small><?= e($delivery['last_error']) ?></small><?php endif; ?></td><td><?= (int)$delivery['attempts'] ?></td><td><?= e($delivery['sent_at']??$delivery['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$mailRecent): ?><p class="muted">Aucun envoi enregistré pour ce projet.</p><?php endif; ?><form method="post" action="/projects/<?= (int)$project['id'] ?>/notifications/retry"><?= csrf() ?><input type="hidden" name="_return" value="/settings?project=<?= (int)$project['id'] ?>#notifications"><button class="button subtle">Réessayer les envois en échec</button></form></details>
<?php endif; ?>
<div class="email-transport"><h3>Transport de messagerie</h3><p>Mode : <strong><?= e(env('MAIL_TRANSPORT','mail')) ?></strong> · Expéditeur : <strong><?= e(env('MAIL_FROM')) ?></strong></p><?php if(env('APP_ENV')==='local' && env('MAIL_TRANSPORT')==='log'): ?><p class="help-text">Mode local : les e-mails sont écrits dans <code>storage/mail</code>, sans envoi réel. Les notifications sont traitées à la fin des requêtes web.</p><?php else: ?><p class="help-text">Le transport se configure sur le serveur avec <code>MAIL_TRANSPORT</code> et <code>MAIL_FROM</code> dans <code>.env</code>. Le mode <code>mail</code> utilise la messagerie PHP du serveur. Planifiez chaque minute <code>php bin/console.php notifications:send</code> pour traiter les notifications en attente.</p><?php endif; ?><form action="/notifications/test" method="post"><?= csrf() ?><input type="hidden" name="_return" value="/settings#notifications"><button class="button subtle">Envoyer un test à mon adresse</button></form></div>
</section><script type="application/json" id="email-recommended"><?= json_encode(ProjectEmail::defaults(),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR) ?></script>
<?php endif; ?>
